// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actor, uint256 amt) public {
        amt = bound(amt, 0, type(uint256).max);
        vm.assume(actor != address(0));

        vm.deal(actor, amt);

        vm.prank(actor);
        c.addToBalance{value: amt}();

        uint256 reported = c.getBalance(actor);

        assertTrue(reported == amt);
    }
}
